// ---- Derived helpers (read-only convenience) ----
(function () {
  var codes = window.QCODE_DATA.codes;
  var byCode = {};
  for (var i = 0; i < codes.length; i++) byCode[codes[i].code] = codes[i];
  window.QCODE_BY = byCode;
  window.QCODE_LIST = codes.map(function (c) { return c.code; });

  // family lookup: code -> family key
  var famOf = {};
  Object.keys(window.QCODE_FAMILIES).forEach(function (fam) {
    window.QCODE_FAMILIES[fam].forEach(function (c) { famOf[c] = fam; });
  });
  window.QCODE_FAMILY_OF = famOf;

  // confusable lookup: code -> array of partner codes (across all clusters it appears in)
  var confOf = {};
  window.QCODE_DATA.confusables = [["QRO", "QRP"], ["QRQ", "QRS"], ["QRM", "QRN"], ["QRK", "QSA"], ["QSW", "QSX", "QSY"], ["QRT", "QRX", "QRU"], ["QTH", "QTR", "QTC"], ["QSB", "QSD"], ["QUB", "QWX"]];
  window.QCODE_DATA.confusables.forEach(function (cluster) {
    cluster.forEach(function (c) {
      confOf[c] = confOf[c] || [];
      cluster.forEach(function (o) { if (o !== c && confOf[c].indexOf(o) < 0) confOf[c].push(o); });
    });
  });
  window.QCODE_CONFUSABLES_OF = confOf;

  // mnemonic for an unordered pair
  window.qcodeMnemonic = function (a, b) {
    var key = [a, b].sort().join('|');
    return window.QCODE_MNEMONICS[key] || null;
  };
})();

// ---- Value FORMAT that follows each code ----
// The learning target is the code's meaning AND the KIND of value that follows it,
// NOT the literal value. (e.g. QSA takes a 1–5 rating; QRG takes a frequency; QRO takes none.)
(function () {
  // canonical kinds -> bilingual label (used as quiz options so they stay consistent)
  window.QCODE_ARG_KINDS = {
    none:     { pl: 'nic — kod bez wartości', en: 'nothing — code stands alone' },
    level:    { pl: 'liczbę 1–5 (ocena)', en: 'a number 1–5 (a rating)' },
    freq:     { pl: 'częstotliwość (kHz)', en: 'a frequency (kHz)' },
    offset:   { pl: 'częstotliwość lub odstęp (np. „5 up”)', en: 'a frequency or offset (e.g. “5 up”)' },
    time:     { pl: 'czas / godzinę (UTC)', en: 'a time (UTC)' },
    wait:     { pl: 'czas oczekiwania (np. „1 min”)', en: 'a wait time (e.g. “1 min”)' },
    loc:      { pl: 'lokalizację (miejscowość)', en: 'a location (a town)' },
    count:    { pl: 'liczbę (ile sztuk)', en: 'a count (how many)' },
    question: { pl: 'znak „?” (pytanie)', en: 'a “?” (it asks a question)' },
    callsign: { pl: 'znak wywoławczy lub „?”', en: 'a callsign or “?”' },
    weather:  { pl: 'dane meteo (widzialność, chmury, wiatr)', en: 'weather data (visibility, clouds, wind)' },
    sea:      { pl: 'stan morza i siłę wiatru', en: 'sea state & surface wind' }
  };
  // per code: [kind, on-air template]
  var ARG = {
    QRG: ['freq', 'QRG <kHz>'], QRK: ['level', 'QRK <1–5>'], QRL: ['question', 'QRL ?'],
    QRM: ['level', 'QRM <1–5>'], QRN: ['level', 'QRN <1–5>'], QRO: ['none', 'QRO'],
    QRP: ['none', 'QRP'], QRQ: ['none', 'QRQ'], QRS: ['none', 'QRS'], QRT: ['none', 'QRT'],
    QRU: ['none', 'QRU'], QRV: ['none', 'QRV'], QRX: ['wait', 'QRX <czas>'], QRZ: ['callsign', 'QRZ ?'],
    QSA: ['level', 'QSA <1–5>'], QSB: ['none', 'QSB'], QSD: ['none', 'QSD'], QSL: ['none', 'QSL'],
    QSO: ['none', 'QSO'], QSV: ['none', 'QSV'], QSW: ['freq', 'QSW <kHz>'], QSX: ['offset', 'QSX <kHz / up>'],
    QSY: ['freq', 'QSY <kHz>'], QTC: ['count', 'QTC <liczba>'], QTH: ['loc', 'QTH <miejsce>'],
    QTR: ['time', 'QTR <czas>'], QUB: ['weather', 'QUB <dane meteo>'], QWX: ['sea', 'QWX <morze/wiatr>']
  };
  window.QCODE_DATA.codes.forEach(function (c) {
    var a = ARG[c.code] || ['none', c.code];
    var k = window.QCODE_ARG_KINDS[a[0]];
    c.arg = { kind: a[0], tmpl: a[1], pl: k.pl, en: k.en };
  });
})();

// ---- Real-usage enrichment (notes / scales / rarity / question-form / abbreviations) ----
// IMPORTANT: the code MEANINGS and EXAMPLES above are kept VERBATIM from egzaminkf.pl
// (the exam source of truth). This block only ADDS real-world context grounded in ITU /
// ARRL / Wikipedia — it never overrides an exam answer.
(function () {
  // broaden the frequency label (canonically "kHz or MHz") + add a distractor-only "1–9" kind
  window.QCODE_ARG_KINDS.freq = { pl: 'częstotliwość (kHz lub MHz)', en: 'a frequency (kHz or MHz)' };
  window.QCODE_ARG_KINDS.level9 = { pl: 'liczbę 1–9', en: 'a number 1–9' }; // never a correct answer; QSA-trap distractor

  // 1–5 rating scales WITH direction (shown as context in the reveal, never quizzed as a literal value)
  var SCALES = {
    QRK: { dir: 'up-good', lo: { pl: '1 = zła', en: '1 = bad' }, hi: { pl: '5 = doskonała', en: '5 = excellent' } },
    QSA: { dir: 'up-good', lo: { pl: '1 = ledwo słyszalny', en: '1 = scarcely perceptible' }, hi: { pl: '5 = bardzo dobry', en: '5 = very good' } },
    QRM: { dir: 'up-bad', lo: { pl: '1 = brak', en: '1 = nil' }, hi: { pl: '5 = ekstremalne', en: '5 = extreme' } },
    QRN: { dir: 'up-bad', lo: { pl: '1 = brak', en: '1 = nil' }, hi: { pl: '5 = ekstremalne', en: '5 = extreme' } }
  };
  // real-world usage notes (PL/EN)
  var NOTES = {
    QRK: { pl: 'Na paśmie raporty podaje się dziś w systemie RST (R 1–5, S 1–9, T 1–9; np. „59”/„599”), a nie przez QRK/QSA. QRK ≈ R (czytelność).', en: 'On the air today, reports use RST (R 1–5, S 1–9, T 1–9; e.g. “59”/“599”), not QRK/QSA. QRK ≈ R (readability).' },
    QSA: { pl: 'QSA to skala 1–5 (ITU), NIE 1–9 — częsty błąd w polskich źródłach (1–9 to „S” z RST). Dziś używa się RST.', en: 'QSA is 1–5 (ITU), NOT 1–9 — a common mistake in Polish sources (1–9 is the “S” of RST). RST is used today.' },
    QRM: { pl: 'Wyżej = GORZEJ (więcej zakłóceń) — odwrotnie niż przy QRK/QSA.', en: 'Higher = WORSE (more interference) — opposite of QRK/QSA.' },
    QRN: { pl: 'Wyżej = GORZEJ (więcej trzasków) — odwrotnie niż przy QRK/QSA.', en: 'Higher = WORSE (more static) — opposite of QRK/QSA.' },
    QRU: { pl: '„73” (pozdrowienia) to osobny skrót — NIE jest częścią QRU.', en: '“73” (best regards) is a separate sign-off — NOT part of QRU.' },
    QRX: { pl: 'W praktyce QRX = „czekaj”, a liczba to zwykle MINUTY. Formalnie (ITU) podaje GODZINĘ ponownego wywołania.', en: 'In practice QRX = “stand by”; the number is usually MINUTES. Formally (ITU) it states the clock TIME of the next call.' },
    QRQ: { pl: 'Formalnie może podać tempo w WPM (zwykle nadawane samo).', en: 'Formally can carry a speed in WPM (usually sent alone).' },
    QRS: { pl: 'Formalnie może podać tempo w WPM (zwykle nadawane samo).', en: 'Formally can carry a speed in WPM (usually sent alone).' },
    QSX: { pl: 'W pracy DX podaje się odstęp, np. „5 up” (5 kHz wyżej).', en: 'In DX work an offset is given, e.g. “5 up” (5 kHz higher).' },
    QWX: { pl: 'UWAGA: QWX nie jest standardowym kodem Q wg ITU/ICAO — występuje tylko w niektórych polskich listach. Pogodę formalnie opisuje QUB.', en: 'NOTE: QWX is not a standard ITU/ICAO Q-code — it appears only in some Polish lists. Weather is formally QUB.' },
    QUB: { pl: 'Kod meteorologiczny (lotniczo-morski) — rzadko używany w łączności amatorskiej.', en: 'A meteorological (aero/maritime) code — rarely used in amateur contacts.' }
  };
  // how often heard on the air today
  var RARE = ['QSV', 'QSW', 'QSD', 'QTR', 'QRK', 'QSA'];
  var MARITIME = ['QUB', 'QWX'];
  // commonly sent as a bare QUESTION on the air (drives On the Band's "?" trap)
  var QUESTION = ['QRL', 'QRZ', 'QTH', 'QRV', 'QRG', 'QRK', 'QSA', 'QTR', 'QSL', 'QRU', 'QSY', 'QSW', 'QSX', 'QTC', 'QRQ', 'QRS'];

  window.QCODE_DATA.codes.forEach(function (c) {
    if (SCALES[c.code]) c.scale = SCALES[c.code];
    if (NOTES[c.code]) c.note = NOTES[c.code];
    c.usage = MARITIME.indexOf(c.code) >= 0 ? 'maritime' : (RARE.indexOf(c.code) >= 0 ? 'rare' : 'common');
    c.commonQuestion = QUESTION.indexOf(c.code) >= 0;
  });

  // companion (non-Q) abbreviations heard alongside Q-codes — reinforces that 73/RST are NOT Q-codes
  window.QCODE_ABBREVS = [
    { a: 'CQ', pl: 'wywołanie ogólne („szukam łączności”)', en: 'general call (“seeking any contact”)' },
    { a: 'DE', pl: '„od” (przed znakiem nadawcy)', en: '“from” (before the sender’s callsign)' },
    { a: 'K', pl: '„odbiór” / proszę nadawać', en: '“over” / go ahead' },
    { a: 'AR', pl: 'koniec wiadomości', en: 'end of message' },
    { a: 'SK', pl: 'koniec łączności', en: 'end of contact' },
    { a: 'BK', pl: '„break” — szybkie przejście na odbiór', en: '“break” — quick over' },
    { a: 'R', pl: 'odebrane / zrozumiałem', en: 'received / roger' },
    { a: 'RST', pl: 'raport: czytelność–siła–ton (np. „599”)', en: 'report: readability–strength–tone (e.g. “599”)' },
    { a: '73', pl: 'pozdrowienia', en: 'best regards' },
    { a: '88', pl: 'całusy (do/od kobiet)', en: 'love and kisses' },
    { a: 'PSE', pl: 'proszę', en: 'please' },
    { a: 'TNX / TKS', pl: 'dzięki', en: 'thanks' },
    { a: 'FB', pl: '„fine business” — świetnie', en: '“fine business” — great' },
    { a: 'OM', pl: '„old man” — kolega operator', en: '“old man” — fellow operator' },
    { a: 'YL / XYL', pl: 'młoda dama / żona', en: 'young lady / wife' },
    { a: 'HW?', pl: '„jak mnie odbierasz?”', en: '“how do you copy?”' }
  ];
})();

